41	func (d *DB) ListMemoRelations(ctx context.Context, find *store.FindMemoRelation) ([]*store.MemoRelation, error) {
42		where, args := []string{"1 = 1"}, []any{}
43		if find.MemoID != nil {
44			where, args = append(where, "memo_id = "+placeholder(len(args)+1)), append(args, *find.MemoID)
45		}
46		if find.RelatedMemoID != nil {
47			where, args = append(where, "related_memo_id = "+placeholder(len(args)+1)), append(args, *find.RelatedMemoID)
48		}
49		if find.Type != nil {
50			where, args = append(where, "type = "+placeholder(len(args)+1)), append(args, *find.Type)
51		}
52		if len(find.MemoIDList) > 0 {
53			placeholders := make([]string, len(find.MemoIDList))
54			for i, id := range find.MemoIDList {
55				placeholders[i] = placeholder(len(args) + 1)
56				args = append(args, id)
57			}
58			inClause := strings.Join(placeholders, ", ")
59			relatedPlaceholders := make([]string, len(find.MemoIDList))
60			for i, id := range find.MemoIDList {
61				relatedPlaceholders[i] = placeholder(len(args) + 1)
62				args = append(args, id)
63			}
64			where = append(where, fmt.Sprintf("(memo_id IN (%s) OR related_memo_id IN (%s))", inClause, strings.Join(relatedPlaceholders, ", ")))
65		}
66		if len(find.SourceMemoIDList) > 0 {
67			placeholders := make([]string, len(find.SourceMemoIDList))
68			for i, id := range find.SourceMemoIDList {
69				placeholders[i] = placeholder(len(args) + 1)
70				args = append(args, id)
71			}
72			where = append(where, fmt.Sprintf("memo_id IN (%s)", strings.Join(placeholders, ", ")))
73		}
74		if len(find.RelatedMemoIDList) > 0 {
75			placeholders := make([]string, len(find.RelatedMemoIDList))
76			for i, id := range find.RelatedMemoIDList {
77				placeholders[i] = placeholder(len(args) + 1)
78				args = append(args, id)
79			}
80			where = append(where, fmt.Sprintf("related_memo_id IN (%s)", strings.Join(placeholders, ", ")))
81		}
82		if find.MemoFilter != nil {
83			engine, err := filter.DefaultEngine()
84			if err != nil {
85				return nil, err
86			}
87			stmt, err := engine.CompileToStatement(ctx, *find.MemoFilter, filter.RenderOptions{
88				Dialect:           filter.DialectPostgres,
89				PlaceholderOffset: len(args),
90			})
91			if err != nil {
92				return nil, err
93			}
94			if stmt.SQL != "" {
95				where = append(where, fmt.Sprintf("memo_id IN (SELECT id FROM memo WHERE %s)", stmt.SQL))
96				args = append(args, stmt.Args...)
97	
